<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientSubjectTypeAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientSubjectTypeAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientSubjectTypeAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getSubjectType returns null on a freshly created holder.
     */
    public function testSubjectTypeNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSubjectTypeAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isSubjectTypeAssigned());
        $this->assertNull($holder->getSubjectType());
    }
}
class ImplWithTrustedClientSubjectTypeAttributeHolderUnitTest
{
    use TrustedClientSubjectTypeAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedSubjectTypeRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultSubjectType();
    }
}
